// Generated by scripts/stitch-to-react.mjs from Stitch screen "Dev in_ 검색 결과 (9번)" (ce7a72e08a46431499f2a428fb4c1b7e).
// #25: GET /api/questions/search에 연결했다. 검색 조건은 모두 URL 쿼리에 두어 페이지 이동·새로고침에도 유지한다.
import { useEffect, useMemo, useState, type ReactNode } from "react";
import { useSearchParams } from "react-router-dom";
import { getErrorMessage, getFieldErrors } from "../api/client";
import { searchQuestions, type Page, type QuestionListItem as Question } from "../api/question";
import PopularTags from "../components/tag/PopularTags";
import TagAutocomplete from "../components/tag/TagAutocomplete";
import { useCategories } from "../hooks/useTagData";
import Footer from "../components/Footer";
import Header from "../components/Header";
import ListStatus from "../components/ListStatus";
import Pagination from "../components/Pagination";
import QuestionListItem from "../components/QuestionListItem";
import SortTabs from "../components/SortTabs";
import { SORT_TABS } from "../components/questionList";
import { buttonClass, CARD, CHIP, chipClass, FOCUS, INPUT, PAGE_BACKGROUND } from "../components/uiStyles";
import { formatNumber } from "../components/writer";
import {
  ACCEPTED_OPTIONS,
  MAX_TAGS,
  normalizeTag,
  readCondition,
  SCOPES,
  toApiParams,
  toSearchParams,
  type SearchCondition,
} from "../components/search/searchCondition";
import "./SearchResults.css";

type LoadState =
  { status: "loading" } | { status: "error"; message: string } | { status: "done"; data: Page<Question> };

// 검색 조건 한 줄: 휴대폰 폭에서는 이름을 위에, sm 이상에서는 왼쪽에 둔다.
function FilterRow({ label, children }: { label: string; children: ReactNode }) {
  return (
    <div className="flex flex-col sm:flex-row sm:items-center gap-2 sm:gap-4 py-3">
      <span className="text-xs font-extrabold text-devin-ink sm:w-20 shrink-0">{label}</span>
      <div className="flex items-center gap-2 flex-wrap min-w-0">{children}</div>
    </div>
  );
}

const ICON = "material-symbols-outlined text-[15px] leading-none";

export default function SearchResults() {
  const [searchParams, setSearchParams] = useSearchParams();
  const condition = useMemo(() => readCondition(searchParams), [searchParams]);
  const apiParams = useMemo(() => toApiParams(condition), [condition]);
  const requestKey = JSON.stringify(apiParams);
  const [state, setState] = useState<LoadState>({ status: "loading" });
  const [retryKey, setRetryKey] = useState(0);
  const [tagWarning, setTagWarning] = useState("");
  const categories = useCategories();

  useEffect(() => {
    let cancelled = false;
    setState({ status: "loading" });
    searchQuestions(JSON.parse(requestKey))
      .then((data) => {
        if (!cancelled) setState({ status: "done", data });
      })
      .catch((error: unknown) => {
        if (cancelled) return;
        // 400이면 어떤 조건이 틀렸는지 함께 보여준다.
        const reasons = getFieldErrors(error).map((e) => e.reason);
        setState({ status: "error", message: reasons.length > 0 ? reasons.join(" ") : getErrorMessage(error) });
      });
    return () => {
      cancelled = true;
    };
  }, [requestKey, retryKey]);

  // 조건을 바꾸면 1페이지부터 다시 본다. 페이지 이동만 page를 넘긴다.
  function update(next: Partial<SearchCondition>) {
    setSearchParams(toSearchParams({ ...condition, page: 1, ...next }));
    window.scrollTo({ top: 0 });
  }

  function addTag(raw: string) {
    const tag = normalizeTag(raw);
    if (!tag || condition.tags.includes(tag)) return;
    if (condition.tags.length >= MAX_TAGS) {
      setTagWarning(`태그는 최대 ${MAX_TAGS}개까지 고를 수 있어요. 다른 태그를 지우고 골라 주세요.`);
      return;
    }
    setTagWarning("");
    update({ tags: [...condition.tags, tag] });
  }

  function removeTag(tag: string) {
    setTagWarning("");
    update({ tags: condition.tags.filter((t) => t !== tag) });
  }

  // 조건 초기화: 검색어는 두고 나머지 필터를 기본값으로 되돌린다.
  function resetFilters() {
    setTagWarning("");
    update({ categoryId: null, tags: [], startDate: "", endDate: "", accepted: "all", scope: "all" });
  }

  const { keyword, scope } = condition;
  const highlightTitle = keyword && (scope === "all" || scope === "title") ? keyword : undefined;
  const highlightTag = keyword && (scope === "all" || scope === "tag") ? keyword : undefined;
  const hasFilters =
    condition.categoryId !== null ||
    condition.tags.length > 0 ||
    condition.startDate !== "" ||
    condition.endDate !== "" ||
    condition.accepted !== "all" ||
    scope !== "all";
  const data = state.status === "done" ? state.data : null;

  return (
    <div id="page-search-results">
      <div className={`min-h-screen flex flex-col justify-between text-devin-ink ${PAGE_BACKGROUND}`}>
        <Header />

        <main className="max-w-6xl w-full mx-auto px-4 py-6 flex-1">
          <div className="flex items-baseline gap-2 pb-4 min-w-0">
            <h1 className="text-2xl font-black break-all">{keyword ? `‘${keyword}’ 검색 결과` : "검색 결과"}</h1>
            {data && (
              <span className="text-sm font-semibold text-devin-gray tabular-nums">
                {formatNumber(data.totalElements)}개
              </span>
            )}
          </div>

          {/* 검색 조건 (REQ-SEARCH-002~004) */}
          <section className={`${CARD} px-4 py-1 mb-6 divide-y divide-devin-line`} aria-label="검색 조건">
            <FilterRow label="검색 범위">
              {SCOPES.map((option) => (
                <label
                  key={option.value}
                  className={`flex items-center gap-2 h-8 text-sm font-medium mr-2 ${keyword ? "cursor-pointer" : "opacity-[.45]"}`}
                >
                  <input
                    className={`w-4 h-4 text-devin-ink border-devin border-devin-ink focus:ring-0 focus:ring-offset-0 ${FOCUS}`}
                    name="search-results-scope"
                    type="radio"
                    disabled={!keyword}
                    checked={scope === option.value}
                    onChange={() => update({ scope: option.value })}
                  />
                  <span>{option.label}</span>
                </label>
              ))}
              {!keyword && <span className="text-xs text-devin-gray">검색어를 입력하면 고를 수 있어요.</span>}
            </FilterRow>

            <FilterRow label="카테고리">
              <button
                className={chipClass(condition.categoryId === null)}
                type="button"
                aria-pressed={condition.categoryId === null}
                onClick={() => update({ categoryId: null })}
              >
                전체
              </button>
              {categories.map((category) => (
                <button
                  key={category.categoryId}
                  className={chipClass(condition.categoryId === category.categoryId)}
                  type="button"
                  aria-pressed={condition.categoryId === category.categoryId}
                  onClick={() => update({ categoryId: category.categoryId })}
                >
                  {category.name}
                </button>
              ))}
            </FilterRow>

            <FilterRow label="태그">
              {condition.tags.map((tag) => (
                <span key={tag} className={CHIP.removable}>
                  {tag}
                  <button
                    className={CHIP.remove}
                    type="button"
                    aria-label={`${tag} 태그 지우기`}
                    onClick={() => removeTag(tag)}
                  >
                    <span className={ICON} aria-hidden="true">
                      close
                    </span>
                  </button>
                </span>
              ))}
              <TagAutocomplete
                selected={condition.tags}
                onSelect={addTag}
                disabled={condition.tags.length >= MAX_TAGS}
                placeholder="태그 검색 후 Enter"
              />
              {tagWarning && <span className={INPUT.errorText}>{tagWarning}</span>}
              {condition.tags.length > 1 && (
                <span className="text-xs text-devin-gray">선택한 태그가 모두 달린 질문만 보여 줘요.</span>
              )}
            </FilterRow>

            <FilterRow label="작성일">
              <div className="w-40">
                <input
                  className={INPUT.base}
                  type="date"
                  aria-label="시작일"
                  max={condition.endDate || undefined}
                  value={condition.startDate}
                  onChange={(event) => update({ startDate: event.target.value })}
                />
              </div>
              <span className="text-sm font-bold">~</span>
              <div className="w-40">
                <input
                  className={INPUT.base}
                  type="date"
                  aria-label="종료일"
                  min={condition.startDate || undefined}
                  value={condition.endDate}
                  onChange={(event) => update({ endDate: event.target.value })}
                />
              </div>
            </FilterRow>

            <FilterRow label="채택 여부">
              {ACCEPTED_OPTIONS.map((option) => (
                <button
                  key={option.value}
                  className={chipClass(condition.accepted === option.value)}
                  type="button"
                  aria-pressed={condition.accepted === option.value}
                  onClick={() => update({ accepted: option.value })}
                >
                  {option.label}
                </button>
              ))}
            </FilterRow>

            <div className="flex justify-end py-3">
              <button
                className={buttonClass("secondary", "sm")}
                type="button"
                disabled={!hasFilters}
                onClick={resetFilters}
              >
                <span className={ICON} aria-hidden="true">
                  restart_alt
                </span>
                조건 초기화
              </button>
            </div>
          </section>

          <div className="flex justify-end pb-3">
            <SortTabs tabs={SORT_TABS} value={condition.sort} onChange={(sort) => update({ sort })} label="정렬" />
          </div>

          <section
            aria-label="검색 결과 목록"
            aria-busy={state.status === "loading"}
            className={`${CARD} overflow-hidden divide-y-2 divide-devin-ink`}
          >
            {state.status === "loading" && <ListStatus kind="loading">검색하는 중이에요.</ListStatus>}
            {state.status === "error" && (
              <ListStatus
                kind="error"
                action={
                  <button
                    className={buttonClass("secondary", "sm")}
                    type="button"
                    onClick={() => setRetryKey((key) => key + 1)}
                  >
                    다시 시도
                  </button>
                }
              >
                {state.message}
              </ListStatus>
            )}
            {data && data.content.length === 0 && (
              <ListStatus
                kind="empty"
                action={
                  condition.page === 1 && (
                    <div className="flex flex-col items-center gap-2">
                      <span className="text-xs font-bold text-devin-gray">인기 태그로 찾아보기</span>
                      {/* 인기 태그를 누르면 다른 조건 없이 그 태그로만 다시 찾는다. */}
                      <PopularTags
                        limit={6}
                        onSelect={(tag) =>
                          update({
                            keyword: "",
                            scope: "all",
                            categoryId: null,
                            tags: [tag],
                            startDate: "",
                            endDate: "",
                            accepted: "all",
                          })
                        }
                      />
                    </div>
                  )
                }
              >
                <p className="text-base font-extrabold text-devin-ink">검색 결과가 없어요.</p>
                <p className="mt-1 text-xs">
                  {condition.page > 1
                    ? "이 페이지에는 결과가 없어요. 앞 페이지로 돌아가 주세요."
                    : "다른 검색어로 찾아보거나 조건을 줄여 보세요."}
                </p>
              </ListStatus>
            )}
            {data?.content.map((question) => (
              <QuestionListItem
                key={question.questionId}
                question={question}
                highlightTitle={highlightTitle}
                highlightTag={highlightTag}
                onTagClick={addTag}
              />
            ))}
          </section>

          <Pagination page={condition.page} totalPages={data?.totalPages ?? 0} onChange={(page) => update({ page })} />
        </main>

        <Footer />
      </div>
    </div>
  );
}
